[McpServerToolType]
public sealed class CurveWitnessTools(BridgeSession session){
 [McpServerTool(Name="inspect_curve_translation_witnesses",ReadOnly=true,Destructive=false,Idempotent=true,OpenWorld=false)]
 [Description("Passively read complete explicit1..N COMPCURVE controls (N2..32) together with eight pinned face positions/normals, COG, native bounds and raw invariants of the one neighboring SOLID. Requires one curve+one SOLID, idle empty WORLD, raw mm/factor1. Both captures are repeated in the same held context. Returns source/receipt provenance and typed samples, not complete continuous geometry/topology or edit authority. No selection, activation, save, geometry command or screenshot. Full and readonly with separate default-off flag.")]
 public async Task<CallToolResult> Inspect([Description("Fresh same-connection candidate document.")]string candidateDocumentHandle,[Description("COMPCURVE candidate from that same inspection.")]string candidateEntityHandle,[Description("Exact explicit startIndex1,endIndexN, complete N2..32; independently checked against POINT.NUMBER.")]JsonElement range,CancellationToken cancellationToken){
  session.AssertToolAllowed("inspect_curve_translation_witnesses");bool acquired=false,submitted=false;var timer=Stopwatch.StartNew();try{acquired=await session.ReferenceGate.WaitAsync(session.Options.Timeout,cancellationToken);if(!acquired)return DiagnosticTools.Result(new(){["state"]="queue_timeout_before_submission"},true);var r=JsonNode.Parse(range.GetRawText())!.AsObject();CurveTranslationProof.Range(r);var args=session.Candidates.SurfaceReadParameters(candidateDocumentHandle,candidateEntityHandle,59);args["range"]=r;cancellationToken.ThrowIfCancellationRequested();submitted=true;var reply=await session.Ipc.SubmitAsync("recipe.prepare",new(){["recipeId"]="inspect_curve_translation_witnesses",["parameters"]=args},cancellationToken,session.Options.Timeout-timer.Elapsed);if(cancellationToken.IsCancellationRequested||timer.Elapsed>=session.Options.Timeout)throw new ReferenceRejected("curve_witnesses_read_timed_out");if(reply["state"]?.GetValue<string>()!="curve_witnesses_read_observed")return DiagnosticTools.Result(reply,true);var result=ValidateReply(session.Options.BridgeRoot,reply,args);session.Candidates.Observe(reply["after"]!.AsObject());return DiagnosticTools.Result(result);}catch(OperationCanceledException)when(cancellationToken.IsCancellationRequested){return DiagnosticTools.Result(new(){["state"]="cancelled_read",["cadMutationAttempted"]=false},true);}catch(Exception e)when(e is ReferenceRejected or IOException or UnauthorizedAccessException or JsonException or InvalidOperationException or KeyNotFoundException or NullReferenceException){if(submitted)session.Candidates.Clear();return DiagnosticTools.Result(new(){["state"]="curve_witnesses_read_rejected",["errorCode"]=e is ReferenceRejected x?x.Code:"curve_witnesses_unavailable",["cadMutationAttempted"]=false},true);}finally{if(acquired)session.ReferenceGate.Release();}}
 internal static JsonObject ValidateReply(string root,JsonObject reply,JsonObject args){var result=CurveLayoutTools.ValidateReply(root,reply,args,true);void Need(bool v){if(!v)throw new ReferenceRejected("curve_witnesses_proof_invalid");}Need(ArtifactProof.IntegerIs(reply["sameContextCapturePasses"],2)&&ArtifactProof.Boolean(reply["curveControlsQualified"],true));CurveTranslationProof.Range(args["range"]!.AsObject());var source=ArtifactProof.Verified(root,"responses",args["inspectionRequestId"]!.GetValue<string>(),args["inspectionSha256"]!.GetValue<string>(),16000000);int native=SurfaceReadTools.Integer(args["entityKey"]![1]);CurveTranslationProof.Capture(reply["curveWitnesses"]!.AsObject(),source,native);CurveTranslationProof.Capture(reply["recheckedWitnesses"]!.AsObject(),source,native);Need(JsonNode.DeepEquals(reply["curveWitnesses"],reply["recheckedWitnesses"])&&JsonNode.DeepEquals(reply["nativeLayout"],reply["curveWitnesses"]!["layout"])&&JsonNode.DeepEquals(reply["range"],reply["curveWitnesses"]!["range"]));return result;}
 public static McpServerTool[] Create(BridgeSession s){if(!s.CurveWitnessesEnabled)return[];var existing=CurveLayoutTools.Create(s).Single();var schema=JsonNode.Parse(existing.ProtocolTool.InputSchema.GetRawText())!.AsObject();schema["properties"]!["range"]!["properties"]!["startIndex"]=new JsonObject{["type"]="integer",["const"]=1};schema["properties"]!["range"]!["properties"]!["endIndex"]=new JsonObject{["type"]="integer",["minimum"]=2,["maximum"]=32};return[new StrictTool(McpServerTool.Create(new CurveWitnessTools(s).Inspect),s,schema,x=>CurveTranslationProof.Range(x["range"]!.AsObject()))];}
